const reviewMethodJobs=new Set();
const reviewIsNetworkError=error=>error?.name==='TypeError';
let reviewMethodPlan=null;
function reviewMethodFingerprint(n,m){return JSON.stringify({id:n.id,title:n.title,goal:n.goal,five:n.five,version:n.version,domain:n.domain,branch:n.branch,ownership:n.ownership,nodeVisibility:n.visibility,methodId:m.id,titleMethod:m.title,author:m.author,latest:m.versions.at(-1)})}
function reviewMethodStatus(m){if(m.serviceReference)return '服务读取的当时版本；当前公开状态以重新加载为准';const receipts=Array.isArray(m.serviceReceipts)?m.serviceReceipts:[],r=receipts.at(-1);if(!r)return m.author==='点亮演示内容组'?'公开演示':'已存行动档案，教程服务尚未保存';return `上次回执：v${r.sourceVersion} · ${r.visibility==='public'?'服务公开':'服务私人'}${r.sourceVersion!==m.versions.at(-1).number?'；当前新版本尚未提交':''}`}
function reviewMethodResourcesSummary(v){return Array.isArray(v.resourceLinks)&&v.resourceLinks.length?v.resourceLinks.map(r=>`${r.label}：${r.url}（${r.optional?'可选':'必需'}；${r.affiliate?'分成外链':'普通资料'}）`).join('\n'):(v.resource||'没有资料链接')}
function reviewEligibleLights(n){return S.lights.filter(l=>{const e=S.events.find(e=>e.id===l.eventId),k=e?.knowledge;return l.nodeId===n.id&&l.confirmed===true&&l.result?.trim()&&l.evidence?.trim()&&e?.endedAt!==null&&Number.isFinite(e?.endedAt)&&k?.nodeVersion===n.version&&k.nodeTitle===n.title&&k.nodeGoal===n.goal})}
async function reviewKnowledgeRequest(url,{body,headers={},context=reviewContext(),method}={}){if(!reviewContextCurrent(context))throw reviewContextError();const r=await fetch(url,{method:method||(body?'POST':'GET'),credentials:'same-origin',headers:{'X-Action-Account':context.ownerId,...(body?{'Content-Type':'application/json'}:{}),...headers},body:body?JSON.stringify(body):undefined});const v=await r.json();if(!reviewContextCurrent(context))throw reviewContextError();if(!r.ok||!v.ok){const error=Error(v.message||({ACTION_CONFLICT:'行动档案已有新版本，请先核对保存。',METHOD_PUBLICATION_CONFLICT:'教程服务已有新版本，请重新核对。',KNOWLEDGE_LIGHT_REQUIRED:'请先完成并确认同一目标的实践。',METHOD_NOT_AUTHOR:'只能发布本人创建的方法。',PRACTICE_CONFLICT:'服务实践已有新版本，请重新核对；原记录未被覆盖。',PRACTICE_PUBLIC_CONFIRMATION_REQUIRED:'公开条件已变化，请核对本人自证及教程的公开状态；私人记录保留。',PRACTICE_MAPPING_UNAVAILABLE:'当时的方法服务引用尚未匹配，原事件保留。'}[v.code])||'知识服务请求未完成，请重试核对。');error.code=v.code;throw error}return v}
async function reviewPrepareMethod(nid,mid,wanted){
 if(!S.user?.reviewService||!reviewReady||reviewClient.snapshot().ownerId!==S.user.id)throw Error('请先连接本人服务账号。');
 const context=reviewContext(),ownerId=context.ownerId,n=S.nodes.find(n=>n.id===nid),m=n?.methods.find(m=>m.id===mid);if(!m||m.author!==S.user.name)throw Error('方法已变化，请重新打开。');
 const fingerprint=reviewMethodFingerprint(n,m);save();await reviewFlush();
 const remote=await reviewKnowledgeRequest('/api/review-method-publications',{context});
 const current=S.nodes.find(n=>n.id===nid),method=current?.methods.find(m=>m.id===mid);
 if(!reviewContextCurrent(context)||!method||reviewMethodFingerprint(current,method)!==fingerprint)throw Error('核对期间方法或账号已变化，文字已保留，请重新打开。');
 return {context,ownerId,nid,mid,fingerprint,wanted,privateTarget:current.ownership==='personal'&&current.visibility==='private',old:remote.tutorials.find(t=>t.sourceOrigin?.nodeId===nid&&t.sourceOrigin?.methodId===mid),lights:reviewEligibleLights(current).map(l=>({id:l.id,eventId:l.eventId,result:l.result,evidence:l.evidence}))};
}
function reviewShowMethodPlan(plan){
 reviewMethodPlan=plan;const n=S.nodes.find(n=>n.id===plan.nid),m=n.methods.find(m=>m.id===plan.mid),v=m.versions.at(-1);
 modal(`<h2>保存到知识服务</h2><p class="small muted">行动档案中的文字已保留。公开仅分享这个方法，不分享点亮证据、私人笔记或计时内容。</p><h3 style="margin-top:18px">${esc(n.title)} · ${esc(m.title)} v${v.number}</h3><p class="pre small">${esc(n.goal)}</p><details class="saved-notes"><summary>核对本次方法</summary><p class="pre">${esc(v.content)}</p><p class="pre small">五分钟起步：${esc(v.five)}</p><p class="pre small">资料：${esc(reviewMethodResourcesSummary(v))}</p></details>${plan.old?`<details class="saved-notes"><summary>服务当前版本：${esc(plan.old.title)}</summary><p class="pre">${esc(plan.old.method)}</p><p class="small muted">${plan.old.visibility==='public'?'当前公开':'当前私人'}；原版本保留，新内容不会改写过去实践。</p></details>`:''}<form id="review-method-publish-form" data-method="${esc(plan.mid)}" class="stack"><label class="field">保存范围<select name="visibility" aria-label="教程服务保存范围"><option value="private" ${plan.wanted==='private'?'selected':''}>私人保存到本人账号</option><option value="public" ${plan.wanted==='public'?'selected':''}>公开到知识服务</option></select></label><section id="review-method-public-options"><label class="field">本人点亮依据<select name="light" aria-label="公开方法的点亮依据">${plan.lights.map(l=>`<option value="${esc(l.id)}">${esc(l.result)}</option>`).join('')}</select></label>${plan.lights.length?'':'<p class="small muted">暂无匹配的本人确认点亮，仍可私人保存。</p>'}<label class="check-row"><input type="checkbox" name="consent">我确认公开以上方法给其他账号</label></section>${plan.old?.visibility==='public'?'<label id="review-method-withdraw" class="check-row"><input type="checkbox" name="withdraw">我选择撤回服务公开，当前方法改为私人</label>':''}<p id="review-method-publish-error" class="error" role="alert"></p><button class="primary">确认保存到知识服务</button></form><div class="row actions">${btn('重新核对服务版本','review-method-refresh','ghost')}${btn('暂不提交','dialog-close','ghost')}</div>`,'','核对教程服务保存');
 const f=document.getElementById('review-method-publish-form'),visibility=f.elements.namedItem('visibility');
 if(plan.privateTarget){visibility.value='private';visibility.querySelector('[value="public"]').disabled=true;const info=document.createElement('p');info.className='small muted';info.textContent='目标在服务中仍为私人，方法只对本人保存；目标分享需另行核对。';f.prepend(info)}
 const update=()=>{const pub=visibility.value==='public';document.getElementById('review-method-public-options').hidden=!pub;f.elements.namedItem('consent').required=pub;const withdraw=f.elements.namedItem('withdraw');if(withdraw){withdraw.required=!pub;document.getElementById('review-method-withdraw').hidden=pub}};visibility.addEventListener('change',update);update();
 f.addEventListener('submit',ev=>{ev.preventDefault();if(!f.reportValidity())return;const pub=visibility.value==='public';reviewCommitMethod(plan,pub?'public':'private',pub?f.elements.namedItem('light').value:null,f)});
}
function reviewMethodFailure(nid,mid,wanted,error){if(error.code==='ACTION_ACCOUNT_CHANGED'||error.code==='UNAUTHENTICATED'){reviewReady=false;reviewSyncWarning('服务账号已变化，原方法文字保留，请重新登录。')}modal(`<h2>教程服务提交尚未完成</h2><p class="pre">${esc(reviewIsNetworkError(error)?'连接未完成，请核对后重试。':error.message)}</p><p class="small muted">填写内容保留在本人行动档案中；没有凭此错误认定方法已公开。</p><div class="row actions">${btn('重新核对并提交',`review-method-open:${nid}:${mid}:${wanted}`)}${btn('保留内容，稍后再做','dialog-close','ghost')}</div>`,'','教程服务提交状态')}
async function reviewOpenMethodPublication(nid,mid,wanted='public'){const context=reviewContext();try{reviewShowMethodPlan(await reviewPrepareMethod(nid,mid,wanted))}catch(error){if(reviewContextCurrent(context))reviewMethodFailure(nid,mid,wanted,error)}}
async function reviewCommitMethod(plan,visibility,lightId,form=null){
 const key=JSON.stringify([plan.ownerId,plan.context.generation,plan.mid]);if(reviewMethodJobs.has(key))return;reviewMethodJobs.add(key);const button=form?.querySelector('button');if(button)button.disabled=true;
 try{
  const n=S.nodes.find(n=>n.id===plan.nid),m=n?.methods.find(m=>m.id===plan.mid);
  if(!reviewContextCurrent(plan.context)||!m||reviewMethodFingerprint(n,m)!==plan.fingerprint)throw Error('方法或账号已有变化，请重新核对。');
  if(visibility==='public'){const current=reviewEligibleLights(n).find(l=>l.id===lightId),shown=plan.lights.find(l=>l.id===lightId);if(!current||!shown||current.result!==shown.result||current.evidence!==shown.evidence||current.eventId!==shown.eventId)throw Error('点亮依据尚未确认或已有变化，请重新核对。')}
  save();await reviewFlush();
  const result=await reviewKnowledgeRequest('/api/review-method-publications',{context:plan.context,body:{nodeId:plan.nid,methodId:plan.mid,sourceVersion:m.versions.at(-1).number,visibility,...(visibility==='public'?{lightId,publicConsent:true}:{})},headers:{'If-Match':reviewClient.snapshot().revision,...(plan.old?{'If-Method-Match':plan.old.version}:{})}});
  if(!reviewContextCurrent(plan.context))throw Error('账号已变化，请在原账户核对服务回执。');
  const t=result.tutorial,b=result.binding;if(t?.authorId!==plan.ownerId||t.visibility!==visibility||b?.source?.source?.id!==plan.mid||b?.service?.id!==t.id||b.service.version!==t.version)throw Error('服务回执与本次选择不一致，请重新核对。');
  const currentNode=S.nodes.find(n=>n.id===plan.nid),current=currentNode?.methods.find(m=>m.id===plan.mid);
  if(current){if(!Array.isArray(current.serviceReceipts))current.serviceReceipts=[];if(!current.serviceReceipts.some(r=>r.id===t.id&&r.version===t.version&&r.sourceVersion===b.source.source.number&&r.sourceHash===b.source.sourceHash))current.serviceReceipts.push({id:t.id,version:t.version,visibility:t.visibility,sourceVersion:b.source.source.number,nodeVersion:b.source.ref.sourceVersion,targetVersion:b.source.ref.targetVersion,sourceHash:b.source.sourceHash,at:Date.now()});if(reviewMethodFingerprint(currentNode,current)===plan.fingerprint)current.visibility=t.visibility}
  if(form&&document.getElementById('review-method-publish-form')===form)closeModal();save();render(false);toast(visibility==='public'?'方法已由知识服务确认公开，私人证据没有公开。':'私人方法已由知识服务确认保存。');
 }catch(error){if(!reviewContextCurrent(plan.context))return;const target=form&&document.getElementById('review-method-publish-error');if(target)target.textContent=reviewIsNetworkError(error)?'连接未完成，文字已保留，请重新核对。':error.message;else reviewMethodFailure(plan.nid,plan.mid,visibility,error)}
 finally{reviewMethodJobs.delete(key);if(button)button.disabled=false}
}
async function reviewSavePrivateMethod(nid,mid){const context=reviewContext();try{const plan=await reviewPrepareMethod(nid,mid,'private');if(plan.old)reviewShowMethodPlan(plan);else await reviewCommitMethod(plan,'private',null)}catch(error){if(reviewContextCurrent(context))reviewMethodFailure(nid,mid,'private',error)}}
function submitMethod(form,copy=false){
 if(!S.user?.reviewService)return submitMethodLocal(form,copy);
 const n=S.nodes.find(n=>n.id===form.dataset.node),flag=form.elements.namedItem('public'),wanted=!!flag?.checked&&!copy;
 if(flag)flag.checked=false;const method=submitMethodLocal(form,copy);if(flag)flag.checked=wanted;
 if(!method)return;
 if(wanted)reviewOpenMethodPublication(n.id,method.id,'public');else reviewSavePrivateMethod(n.id,method.id);
}
function methodForm(n,existing=null){methodFormLocal(n,existing);if(S.user?.reviewService&&n.ownership==='personal'&&n.visibility==='private'){const flag=document.querySelector('#method-form [name="public"]');if(flag){flag.checked=false;flag.disabled=true;flag.parentElement.append(document.createTextNode('（目标仍为私人）'))}}}
